//! Original Node vectors and native provider integration/ownership proofs.
use super::*;
use serde_json::{Value, json};
use std::{collections::HashSet, sync::Arc};

/// Fixture was generated by direct imports from original helpers and CUID2 3.3.0.
fn vectors() -> Value {
    serde_json::from_str(include_str!("vectors.json")).unwrap()
}
#[test]
fn original_crypto_vectors() {
    for v in vectors()["cryptoVectors"].as_array().unwrap() {
        let (value, seed, cipher) = (
            v["value"].as_str().unwrap(),
            v["seed"].as_str().unwrap(),
            v["ciphertext"].as_str().unwrap(),
        );
        assert_eq!(encrypt(value, seed), cipher);
        assert_eq!(decrypt(cipher, seed).unwrap(), value);
        assert_eq!(hash(value), v["hash"]);
        // Buffer.from(hex) accepts case and stops at an invalid suffix or odd trailing nibble.
        assert_eq!(
            decrypt(&format!("{}zz1", cipher.to_uppercase()), seed).unwrap(),
            value
        );
        assert_eq!(decrypt(&format!("{cipher}1"), seed).unwrap(), value);
    }
}
#[test]
fn malformed_ciphertext_and_wrong_seed_fail() {
    for value in ["", "zz", "00", "00000000000000000000000000000000"] {
        assert!(decrypt(value, "abc123").is_err());
    }
    assert!(decrypt(&encrypt("fixture", "abc123"), "other").is_err());
    assert_eq!(encrypt("fixture", "abc123"), encrypt("fixture", "abc123"));
}
#[test]
fn cuid2_original_init_vectors() {
    for v in vectors()["cuidVectors"].as_array().unwrap() {
        assert_eq!(
            super::cuid::format_id(
                v["time"].as_u64().unwrap().into(),
                v["salt"].as_str().unwrap(),
                v["counter"].as_u64().unwrap(),
                v["fingerprint"].as_str().unwrap(),
                v["first"].as_str().unwrap().chars().next().unwrap(),
                v["length"].as_u64().unwrap() as usize
            ),
            v["id"]
        );
    }
}
#[test]
fn native_cuid_generation_and_lengths() {
    for length in [2, 24, 32] {
        let id = CuidGenerator::with_length(length)
            .unwrap()
            .generate()
            .unwrap();
        assert_eq!(id.len(), length);
        assert!(id.as_bytes()[0].is_ascii_lowercase());
        assert!(
            id.bytes()
                .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit())
        );
    }
    for length in [0, 1, 33] {
        assert!(CuidGenerator::with_length(length).is_err());
    }
    assert_eq!(cuid().unwrap().len(), 24);
}
#[test]
fn concurrent_owned_cuid_generator() {
    let generator = Arc::new(CuidGenerator::new().unwrap());
    let jobs: Vec<_> = (0..8)
        .map(|_| {
            let generator = generator.clone();
            std::thread::spawn(move || {
                (0..128)
                    .map(|_| generator.generate().unwrap())
                    .collect::<Vec<_>>()
            })
        })
        .collect();
    let ids: Vec<_> = jobs.into_iter().flat_map(|j| j.join().unwrap()).collect();
    assert_eq!(ids.len(), 1024);
    assert_eq!(ids.into_iter().collect::<HashSet<_>>().len(), 1024);
}
#[test]
fn existing_value_provider_mechanism() {
    use crate::{ValueContext, ValueRule, ValueType};
    let providers = BuiltinProviders;
    let context = ValueContext {
        providers: Some(&providers),
        ..Default::default()
    };
    let rule = ValueRule {
        provider: "cuid".into(),
        args: vec![],
        revision: "cuid2-3.3.0".into(),
    };
    assert_eq!(
        rule.resolve_for(&ValueType::String, &context)
            .unwrap()
            .as_str()
            .unwrap()
            .len(),
        24
    );
    // Source init accepts length one despite its maximum-only diagnostic wording.
    assert_eq!(
        providers
            .generate("cuid", &[json!(1)])
            .unwrap()
            .as_str()
            .unwrap()
            .len(),
        1
    );
    assert!(providers.generate("cuid", &[json!(33)]).is_err());
    assert!(providers.generate("other", &[]).is_err());
    assert!(providers.validate("remote", &json!(null), &[]).is_err());
    assert!(rule.resolve_for(&ValueType::Integer, &context).is_err());
}

#[cfg(feature = "codegen")]
#[test]
fn normalized_cuid_default_uses_builtin_value_provider() {
    use crate::{
        Schema, ValueContext,
        codegen::{DefinitionRegistry, NormalizeOptions},
    };
    use stackpress_idea_parser::{CompileInputs, parse};
    let registry = DefinitionRegistry::standard()
        .with_provider(cuid_definition())
        .unwrap();
    let config = parse(
        "cuid.idea",
        "model Person { id String @id @generated @default(\"cuid()\") }",
        &CompileInputs::default(),
    )
    .unwrap();
    let schema = Schema::normalize(&config, &registry, NormalizeOptions::default()).unwrap();
    let rule = schema.models()[0].fields[0].value_rule.as_ref().unwrap();
    assert_eq!(rule.provider, "cuid");
    let providers = BuiltinProviders;
    let context = ValueContext {
        providers: Some(&providers),
        ..Default::default()
    };
    assert_eq!(rule.resolve(&context).unwrap().as_str().unwrap().len(), 24);
}
